INSERT INTO _e VALUES
 ('ENT_LUW_PANTHEON','The Luwian Pantheon','Collective','Pantheon','Luwian','the gods of the Luwian-speaking peoples of Bronze and Iron Age Anatolia and northern Syria','A','Collective hub wiring the Luwian gods (Tarhunz, Tiwaz, Arma, Runtiya, Santa, Iyarri, Maliya, Kubaba) into the regional pantheon system (Taracha).'),
 ('ENT_HTT_PANTHEON','The Hittite Pantheon','Collective','Pantheon','Hittite','the ''thousand gods of Hatti''; the Hittite-Hurrian state pantheon of Bronze Age Anatolia','A','Collective hub for the Hittite/Hurrian state pantheon (''the thousand gods of Hatti'').'),
 ('ENT_PHO_PANTHEON','The Phoenician Pantheon','Collective','Pantheon','Phoenician','kingship; storm; sea; healing; fertility; city-tutelary cult of Tyre, Sidon, Byblos, Carthage','A','Collective hub for the Phoenician/Punic civic gods.'),
 ('ENT_MYC_PANTHEON','The Mycenaean Pantheon','Collective','Pantheon','Mycenaean','Linear B cult; Bronze-Age Aegean religion','A','Collective hub for the Linear B cult-recipients (Pylos/Knossos), distinct from the later Olympian system; ENT_MYC_TN316 is a sub-collective.'),
 ('ENT_ETR_PANTHEON','The Etruscan Pantheon','Collective','Pantheon','Etruscan','Etruscan religion; liver-divination; chthonic and celestial cult','A','Collective hub for the Etruscan gods.');
