INSERT INTO _p VALUES
 ('ENT_LUW_PANTHEON','PER_LUW_NEO_HITTITE','Collective hub wiring the Luwian gods (Tarhunz, Tiwaz, Arma, Runtiya, Santa, Iyarri, Maliya, Kubaba) into the regional pantheon system (Taracha).'),
 ('ENT_HTT_PANTHEON','PER_HTT_EMPIRE','Collective hub for the Hittite/Hurrian state pantheon (''the thousand gods of Hatti'').'),
 ('ENT_PHO_PANTHEON','PER_PHO_IRON_AGE','Collective hub for the Phoenician/Punic civic gods.'),
 ('ENT_MYC_PANTHEON','PER_GRK_MYCENAEAN','Collective hub for the Linear B cult-recipients (Pylos/Knossos), distinct from the later Olympian system; ENT_MYC_TN316 is a sub-collective.'),
 ('ENT_ETR_PANTHEON','PER_ETR_CLASSICAL','Collective hub for the Etruscan gods.');
