INSERT INTO _r VALUES
 ('ENT_LUW_TARHUNZ','member_of','ENT_LUW_PANTHEON','high','Tarhunz is the chief storm-god of the Luwian pantheon.'),
 ('ENT_LUW_TIWAZ','member_of','ENT_LUW_PANTHEON','high','Tiwaz is the Luwian sun-god.'),
 ('ENT_LUW_ARMA','member_of','ENT_LUW_PANTHEON','high','Arma is the Luwian moon-god.'),
 ('ENT_LUW_RUNTIYA','member_of','ENT_LUW_PANTHEON','high','Runtiya is the Luwian stag/tutelary god.'),
 ('ENT_LUW_SANTA','member_of','ENT_LUW_PANTHEON','high','Santa is a Luwian plague/war god.'),
 ('ENT_LUW_IYARRI','member_of','ENT_LUW_PANTHEON','high','Iyarri is the Luwian plague/war archer god.'),
 ('ENT_LUW_MALIYA','member_of','ENT_LUW_PANTHEON','high','Maliya is the Luwian goddess of rivers, gardens, and crafts.'),
 ('ENT_LUW_KUBABA','member_of','ENT_LUW_PANTHEON','high','Kubaba, the enthroned city-goddess, is a high deity of the Luwian (Iron Age Syro-Anatolian) pantheon.'),
 ('ENT_ARA_KUBABA','cult_form_of','ENT_LUW_KUBABA','high','''Kubaba of Carchemish'' is the city-cult form of the goddess Kubaba, whose principal cult center was Carchemish.'),
 ('ENT_LUW_TARHUNZ','aligned_with','ENT_HTT_TESHUB','high','Functional storm-sovereign cognate; in Syro-Anatolian Iron Age cult Tarhunz and Hurrian Teshub overlap as the supreme storm-god.'),
 ('ENT_LUW_TARHUNZ','aligned_with','ENT_ZEUS','medium','Storm-sovereign typological cognate; later interpretatio identifies the Anatolian storm-god (Zeus Dolichenus continuity) with Zeus.'),
 ('ENT_LUW_KUBABA','received_as','ENT_CYBELE','high','Classic Kubaba > Kybebe > Cybele continuity: the Syro-Anatolian goddess Kubaba is the etymological and cultic forerunner of Phrygian/Greek Cybele (Burkert, West).'),
 ('ENT_LUW_TIWAZ','aligned_with','ENT_HTT_ISTANU','high','Luwian sun-god Tiwaz and Hittite sun-god Istanu are functional cognates (sun, justice, oaths).'),
 ('ENT_LUW_TIWAZ','aligned_with','ENT_HTT_SHIMIGE','medium','Tiwaz aligns with the Hurrian sun-god Shimige as the regional sun/justice deity.'),
 ('ENT_LUW_ARMA','aligned_with','ENT_HTT_KUSHUH','high','Luwian moon-god Arma and Hurrian moon-god Kushuh are functional cognates (moon, oaths).'),
 ('ENT_LUW_RUNTIYA','aligned_with','ENT_ARTEMIS','medium','Runtiya, the stag/hunt/wild-protection god, is the typological forerunner/cognate of the Anatolian Artemis (mistress of wild animals and the hunt).'),
 ('ENT_LUW_RUNTIYA','aligned_with','ENT_APOLLO','low','Runtiya has been linked to Apollo in the Anatolian-tutelary-god discussion; offered low (the Artemis association is stronger).'),
 ('ENT_LUW_SANTA','aligned_with','ENT_MES_MARDUK','medium','Santa (Sanda) is attested in Anatolian-Mesopotamian syncretism with Marduk, sharing warrior/plague aspects.'),
 ('ENT_LUW_IYARRI','aligned_with','ENT_APOLLO','medium','Iyarri, the plague-bringing archer (''lord of the bow''), is the recognized Anatolian forerunner-type of the plague-archer Apollo (Smintheus).'),
 ('ENT_LUW_ARMA','presides_over','ENT_MOON','high','Arma is the Luwian moon-god.'),
 ('ENT_LUW_MALIYA','presides_over','ENT_CRAFT','medium','Maliya''s domains include crafts (alongside rivers and gardens, the latter wired via ENT_WATER).'),
 ('ENT_LUW_IYARRI','presides_over','ENT_WAR','high','Iyarri is a plague-and-war god leading armies.'),
 ('ENT_LUW_SANTA','presides_over','ENT_WAR','high','Santa is a plague-and-war god.'),
 ('ENT_LUW_TIWAZ','presides_over','ENT_SUN','high','Tiwaz is the Luwian sun-god.'),
 ('ENT_LUW_TIWAZ','presides_over','ENT_JUSTICE','high','Tiwaz governs justice and oaths, the standard Anatolian sun-god judicial role.'),
 ('ENT_LUW_KUBABA','presides_over','ENT_FERTILITY','medium','Kubaba''s domains include fertility/nature (pomegranate, lion iconography).'),
